-- =============================================================================
--  boot_loader.vhd  -  Hardware boot path for synchronous (SRAM) IMEM
--  License: MIT
--
--  ASIC SRAM powers up with undefined contents and cannot be initialised from
--  a file. After reset this block copies the boot ROM (rv32_bootrom_pkg,
--  a synthesizable VHDL constant generated by gen_bootrom_pkg.py) into the
--  IMEM through the same port the AXI-Lite IMEM window uses, zero-fills the
--  rest of the IMEM (so a stray jump hits an illegal instruction, not random
--  bits), and only then releases the core ('busy' = '0').
--
--  One word per cycle: DEPTH cycles after reset. The SoC muxes this port in
--  front of axil_soc's IMEM port while busy = '1' and holds the core in
--  reset; afterwards the host can still (re)load the IMEM through axil_soc.
-- =============================================================================
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

use work.riscv_pkg.all;
use work.rv32_bootrom_pkg.all;

entity boot_loader is
  generic (
    DEPTH : natural := 256                -- IMEM words
  );
  port (
    clk     : in  std_logic;
    aresetn : in  std_logic;
    busy    : out std_logic;              -- '1' while copying (core held in reset)
    addr    : out word_t;                 -- byte address into the IMEM
    wdata   : out word_t;
    wstrb   : out std_logic_vector(3 downto 0)
  );
end entity boot_loader;

architecture rtl of boot_loader is
  signal idx    : natural range 0 to DEPTH := 0;
  signal busy_q : std_logic := '1';
begin
  assert BOOT_ROM'length <= DEPTH
    report "boot_loader: boot ROM larger than the IMEM" severity failure;

  busy  <= busy_q;
  addr  <= std_logic_vector(to_unsigned(idx * 4, XLEN)) when idx < DEPTH else (others => '0');
  wdata <= BOOT_ROM(BOOT_ROM'low + idx) when idx < BOOT_ROM'length else (others => '0');
  wstrb <= "1111" when (busy_q = '1' and idx < DEPTH) else "0000";

  process(clk)
  begin
    if rising_edge(clk) then
      if aresetn = '0' then
        idx    <= 0;
        busy_q <= '1';
      elsif busy_q = '1' then
        if idx = DEPTH - 1 then
          busy_q <= '0';
        end if;
        if idx < DEPTH then
          idx <= idx + 1;
        end if;
      end if;
    end if;
  end process;
end architecture rtl;
